// Reads the date and morning/afternoon preference sent by Retell's check_availability function
const cfg = $('Set Shop Configuration').first().json;
const body = $('Retell Webhook Endpoint').first().json.body || {};
const args = body.args || {};
const tz = cfg.timezone;

const day = DateTime.fromISO(String(args.date || args.appointment_date || '').trim(), { zone: tz });
const timeOfDay = String(args.time_of_day || args.time || 'morning').toLowerCase().includes('after') ? 'afternoon' : 'morning';
const valid = day.isValid;
const range = valid ? day : DateTime.now().setZone(tz);

return [{
  json: {
    valid,
    date: valid ? day.toISODate() : null,
    time_of_day: timeOfDay,
    time_min: range.startOf('day').toISO(),
    time_max: range.endOf('day').toISO()
  }
}];

// Compares the shop's slot hours with events already on the calendar
const cfg = $('Set Shop Configuration').first().json;
const req = $('Parse Slot Availability Request').first().json;
if (!req.valid) {
  return [{ json: { success: false, available_slots: [], message: "I didn't catch the date. Ask the caller for the day again." } }];
}

const tz = cfg.timezone;
const closed = String(cfg.closedDays || '').toLowerCase().split(',').map(d => d.trim()).filter(Boolean);
const weekday = DateTime.fromISO(req.date, { zone: tz }).setLocale('en').toFormat('cccc').toLowerCase();
if (closed.includes(weekday)) {
  return [{ json: { success: false, available_slots: [], message: `The shop is closed on ${weekday}s. Offer another day.` } }];
}
const length = Number(cfg.appointmentMinutes) || 60;
const hours = String(req.time_of_day === 'afternoon' ? cfg.afternoonHours : cfg.morningHours)
  .split(',').map(h => parseInt(h, 10)).filter(h => !isNaN(h));

let allDayBlock = false;
const busy = [];
for (const item of $input.all()) {
  const s = item.json.start, e = item.json.end;
  if (!s) continue;                                        // empty day
  if (s.date && !s.dateTime) { allDayBlock = true; continue; } // all-day event blocks the day
  busy.push([DateTime.fromISO(s.dateTime).toMillis(), DateTime.fromISO(e.dateTime).toMillis()]);
}

const now = DateTime.now().setZone(tz);
const free = [];
for (const h of hours) {
  const start = DateTime.fromISO(req.date, { zone: tz }).set({ hour: h, minute: 0 });
  const end = start.plus({ minutes: length });
  if (start <= now) continue;
  const clash = allDayBlock || busy.some(([bs, be]) => start.toMillis() < be && end.toMillis() > bs);
  if (!clash) free.push(start.toFormat('h:mm a'));
}

const other = req.time_of_day === 'morning' ? 'afternoon' : 'morning';
return [{
  json: {
    success: free.length > 0,
    date: req.date,
    time_of_day: req.time_of_day,
    available_slots: free,
    message: free.length
      ? `Open ${req.time_of_day} times on ${req.date}: ${free.join(', ')}.`
      : `No ${req.time_of_day} times left on ${req.date}. Offer another day or the ${other}.`
  }
}];

// Reads the booking details sent by Retell's book_appointment function
const cfg = $('Set Shop Configuration').first().json;
const body = $('Retell Webhook Endpoint').first().json.body || {};
const args = body.args || {};
const tz = cfg.timezone;
const length = Number(cfg.appointmentMinutes) || 60;

function parseSlot(date, time, tz) {
  const day = DateTime.fromISO(String(date || '').trim(), { zone: tz });
  const m = String(time || '').match(/(\d{1,2})(?::(\d{2}))?\s*([ap])\.?\s*m/i);
  if (!day.isValid || !m) return null;
  let h = parseInt(m[1], 10) % 12;
  if (m[3].toLowerCase() === 'p') h += 12;
  return day.set({ hour: h, minute: m[2] ? parseInt(m[2], 10) : 0, second: 0, millisecond: 0 });
}

const name = String(args.caller_name || '').trim() || 'Unknown caller';
const phone = String(args.caller_phone || '').trim() || String(body.call?.from_number || '') || 'Not provided';
const vehicle = String(args.vehicle || '').trim() || 'Not specified';
const service = String(args.service_needed || args.service || '').trim() || 'General service';
const start = parseSlot(args.appointment_date || args.date, args.appointment_time || args.time, tz);
const range = start || DateTime.now().setZone(tz);
const end = range.plus({ minutes: length });

return [{
  json: {
    valid: !!start,
    caller_name: name,
    caller_phone: phone,
    vehicle,
    service,
    start_iso: range.toISO(),
    end_iso: end.toISO(),
    date_label: range.toFormat('cccc, LLL d'),
    time_label: range.toFormat('h:mm a'),
    event_title: `${cfg.eventTitlePrefix} - ${name}`,
    event_description: `Name: ${name}\nPhone: ${phone}\nVehicle: ${vehicle}\nService: ${service}\nBooked by: AI phone receptionist`
  }
}];

// Double-booking guard: any event overlapping the requested slot blocks the booking
const req = $('Parse Appointment Booking Request').first().json;
if (!req.valid) {
  return [{ json: { can_book: false, message: "I need the date and time again before I can book it." } }];
}
const cfg = $('Set Shop Configuration').first().json;
const closed = String(cfg.closedDays || '').toLowerCase().split(',').map(d => d.trim()).filter(Boolean);
const weekday = DateTime.fromISO(req.start_iso).setZone(cfg.timezone).setLocale('en').toFormat('cccc').toLowerCase();
if (closed.includes(weekday)) {
  return [{ json: { can_book: false, message: `The shop is closed on ${weekday}s. Offer another day.` } }];
}
const now = DateTime.now().toMillis();
const start = DateTime.fromISO(req.start_iso).toMillis();
if (start <= now) {
  return [{ json: { can_book: false, message: 'That time has already passed. Please pick a later time.' } }];
}
const taken = $input.all().some(item => item.json.start);
return [{
  json: {
    can_book: !taken,
    message: taken ? 'Sorry, that time was just taken. Check availability again and offer another time.' : 'Slot is free.'
  }
}];

// Reads the caller name and appointment date sent by Retell's cancel_appointment function
const cfg = $('Set Shop Configuration').first().json;
const body = $('Retell Webhook Endpoint').first().json.body || {};
const args = body.args || {};
const tz = cfg.timezone;

const day = DateTime.fromISO(String(args.appointment_date || args.date || '').trim(), { zone: tz });
const range = day.isValid ? day : DateTime.now().setZone(tz);

return [{
  json: {
    valid: day.isValid,
    caller_name: String(args.caller_name || '').trim(),
    appointment_date: day.isValid ? day.toISODate() : null,
    time_min: range.startOf('day').toISO(),
    time_max: range.endOf('day').toISO()
  }
}];

// Finds the caller's appointment on that day by matching their name in the event title
const cfg = $('Set Shop Configuration').first().json;
const req = $('Parse Cancellation Request').first().json;
const name = String(req.caller_name || '').toLowerCase();

if (!req.valid || !name) {
  return [{ json: { found: false, message: 'I need the name and date of the appointment to find it.' } }];
}

const match = $input.all().find(item => String(item.json.summary || '').toLowerCase().includes(name));
if (!match) {
  return [{ json: { found: false, message: "I couldn't find an appointment under that name on that date. Can you double-check the name or date?" } }];
}

const start = DateTime.fromISO(match.json.start?.dateTime || match.json.start?.date).setZone(cfg.timezone);
return [{
  json: {
    found: true,
    event_id: match.json.id,
    event_title: match.json.summary,
    event_details: match.json.description || '',
    old_label: start.toFormat("cccc, LLL d 'at' h:mm a"),
    message: 'Found the appointment.'
  }
}];

// Reads the old date and the new date/time sent by Retell's reschedule_appointment function
const cfg = $('Set Shop Configuration').first().json;
const body = $('Retell Webhook Endpoint').first().json.body || {};
const args = body.args || {};
const tz = cfg.timezone;
const length = Number(cfg.appointmentMinutes) || 60;

function parseSlot(date, time, tz) {
  const day = DateTime.fromISO(String(date || '').trim(), { zone: tz });
  const m = String(time || '').match(/(\d{1,2})(?::(\d{2}))?\s*([ap])\.?\s*m/i);
  if (!day.isValid || !m) return null;
  let h = parseInt(m[1], 10) % 12;
  if (m[3].toLowerCase() === 'p') h += 12;
  return day.set({ hour: h, minute: m[2] ? parseInt(m[2], 10) : 0, second: 0, millisecond: 0 });
}

const oldDay = DateTime.fromISO(String(args.old_date || '').trim(), { zone: tz });
const newStart = parseSlot(args.new_date, args.new_time, tz);
const oldRange = oldDay.isValid ? oldDay : DateTime.now().setZone(tz);
const newRange = newStart || DateTime.now().setZone(tz);

return [{
  json: {
    valid: oldDay.isValid,
    new_valid: !!newStart,
    caller_name: String(args.caller_name || '').trim(),
    time_min: oldRange.startOf('day').toISO(),
    time_max: oldRange.endOf('day').toISO(),
    new_start_iso: newRange.toISO(),
    new_end_iso: newRange.plus({ minutes: length }).toISO(),
    new_label: newRange.toFormat("cccc, LLL d 'at' h:mm a")
  }
}];

// Finds the caller's appointment on that day by matching their name in the event title
const cfg = $('Set Shop Configuration').first().json;
const req = $('Parse Rescheduling Request').first().json;
const name = String(req.caller_name || '').toLowerCase();

if (!req.valid || !name) {
  return [{ json: { found: false, message: 'I need the name and date of the appointment to find it.' } }];
}

const match = $input.all().find(item => String(item.json.summary || '').toLowerCase().includes(name));
if (!match) {
  return [{ json: { found: false, message: "I couldn't find an appointment under that name on that date. Can you double-check the name or date?" } }];
}

const start = DateTime.fromISO(match.json.start?.dateTime || match.json.start?.date).setZone(cfg.timezone);
return [{
  json: {
    found: true,
    event_id: match.json.id,
    event_title: match.json.summary,
    event_details: match.json.description || '',
    old_label: start.toFormat("cccc, LLL d 'at' h:mm a"),
    message: 'Found the appointment.'
  }
}];

// Double-booking guard for the new time (ignores the caller's own original event)
const req = $('Parse Rescheduling Request').first().json;
const original = $('Match Original Appointment').first().json;
if (!req.new_valid) {
  return [{ json: { can_move: false, message: 'I need the new date and time again.' } }];
}
if (DateTime.fromISO(req.new_start_iso).toMillis() <= Date.now()) {
  return [{ json: { can_move: false, message: 'That new time has already passed. Please pick a later time.' } }];
}
const taken = $input.all().some(item => item.json.start && item.json.id !== original.event_id);
return [{
  json: {
    can_move: !taken,
    message: taken ? 'Sorry, that new time is taken. Check availability again and offer another time.' : 'New slot is free.'
  }
}];
